mapper.delete:
delete from TOPO_ASSET_MARK
where ORG_ID = #{orgId}
  and NODE_TYPE = #{nodeType}

delete from TOPO_ASSET_MARK
where ASSET_ID = #{assetId}
  and NODE_TYPE = #{nodeType}

mapper.select:
select *
from TOPO_ASSET_MARK
where ORG_ID = #{orgId}
  and NODE_TYPE = #{nodeType}
order by id

select *
from TOPO_ASSET_MARK
where ASSET_ID = #{assetId}
  and NODE_TYPE = #{nodeType}
order by id desc
